def test_load_attenuators_require_att_setup_set_attenuation_and_reestablish_connection(ta_attenuator):
    ta_attenuator.load_attenuation_config(TA_ATTENUATOR_CONFIG)
    ta_attenuator.require_attenuator_setup_of('ENB_3_CELL_1')
    ta_attenuator.set_attenuation('ENB_3_CELL_1', '10db')
    cell = ta_attenuator.cells_pool.get_cell('ENB_3_CELL_1')
    att = ta_attenuator.attenuators_pool.get_attenuator(cell.used_attenuator[0])
    att.disconnect_attenuator_controller()
    ta_attenuator.set_attenuation('ENB_3_CELL_1', '30db')


