@patch("time.sleep")
def test_can_execute_fading_scenario_with_percentage_values(ta_attenuator):
    ta_attenuator.load_attenuation_config(TA_ATTENUATOR_CONFIG)
    ta_attenuator.require_attenuator_setup_of('ENB_1_CELL_1')
    ta_attenuator.require_attenuator_setup_of('ENB_3_CELL_2')
    ta_attenuator.execute_fading_scenario(source_cell='ENB_1_CELL_1', target_cell='ENB_3_CELL_2',
                                          fading_step='-2db', fading_interval='0.5s', fading_min='100%', fading_max='0%')
    ta_attenuator.execute_fading_scenario(source_cell='ENB_1_CELL_1', target_cell='ENB_3_CELL_2',
                                          fading_step='2db', fading_interval='0.5s', fading_min='0%', fading_max='100%')


@patch("time.sleep")
def test_load_attenuators_require_att_setup_and_start_fading_scenario(ta_attenuator):
    ta_attenuator.load_attenuation_config(TA_ATTENUATOR_CONFIG)
    ta_attenuator.require_attenuator_setup_of('ENB_1_CELL_1')
    ta_attenuator.require_attenuator_setup_of('ENB_1_CELL_2')
    ta_attenuator.start_fading_scenario('Fading1', source_cell='ENB_1_CELL_1', target_cell='ENB_1_CELL_2',
                                        fading_step='2db', fading_interval='0.5s', fading_min='0db', fading_max='50db')
    ta_attenuator.await_finish_of_fading_scenario('Fading1')


def test_set_maximum_attenuation_for_all_cells_of_testline_sets_all_cells_in_config(ta_attenuator):
    ta_attenuator.load_attenuation_config(TA_ATTENUATOR_CONFIG)
    total_rf_paths = 0
    for cell, config in ta_attenuator.cells_pool.cells_registry.items():
        for attenuator in config.cell_config_list:
            total_rf_paths += len(attenuator['rf_paths_at_attenuator'])
    with patch('ta_attenuator.attenuator.Attenuator.set_single_rf_path_attenuation') as patched_set:
        ta_attenuator.set_maximum_attenuation_for_all_cells_of_testline()
        assert patched_set.call_count == total_rf_paths


def test_set_zero_percent_attenuation_when_minimal_attenuation_is_not_equal_to_zero_db(ta_attenuator):
    ta_attenuator.load_attenuation_config(TA_ATTENUATOR_CONFIG)
