def test_set_attenuation_exceeding_maximal_value(ta_attenuator):
    ta_attenuator.load_attenuation_config(TA_ATTENUATOR_CONFIG)
    from ta_attenuator.attenuator import AttenuationOutOfBoundsException
    ta_attenuator.require_attenuator_setup_of('ENB_4_CELL_1')
    with pytest.raises(AttenuationOutOfBoundsException):
        ta_attenuator.set_attenuation('ENB_4_CELL_1', '110%')
    with pytest.raises(AttenuationOutOfBoundsException):
        ta_attenuator.set_attenuation('ENB_4_CELL_1', '91db')


